CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,verified boolean NOT NULL DEFAULT false,settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,personal jsonb NOT NULL,bio text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,agent text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);
CREATE TABLE IF NOT EXISTS auth_tokens (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,hash text NOT NULL UNIQUE,type text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS resumes (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,template text NOT NULL,status text NOT NULL DEFAULT 'draft',personal jsonb NOT NULL,summary text NOT NULL DEFAULT '',style jsonb NOT NULL,revision integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS resumes_owner_idx ON resumes(user_id);
CREATE TABLE IF NOT EXISTS resume_sections (id text PRIMARY KEY,resume_id text NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,key text NOT NULL,position integer NOT NULL,visible boolean NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS sections_resume_key_idx ON resume_sections(resume_id,key);
CREATE TABLE IF NOT EXISTS resume_versions (id text PRIMARY KEY,resume_id text NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,number integer NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS versions_resume_number_idx ON resume_versions(resume_id,number);
CREATE TABLE IF NOT EXISTS templates (id text PRIMARY KEY,name text NOT NULL,category text NOT NULL,layout text NOT NULL);
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['experiences','education','skills','projects','certifications','languages','achievements','awards','publications','volunteer_experiences','interests','resume_references'] LOOP EXECUTE format('CREATE TABLE IF NOT EXISTS %I (id text PRIMARY KEY,resume_id text NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,position integer NOT NULL,fields jsonb NOT NULL)',tbl); EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I(resume_id)',tbl||'_resume_idx',tbl); END LOOP; END $$;
CREATE TABLE IF NOT EXISTS cover_letters (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,resume_id text REFERENCES resumes(id) ON DELETE SET NULL,company text NOT NULL,title text NOT NULL,tone text NOT NULL,content text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS letters_owner_idx ON cover_letters(user_id);
CREATE TABLE IF NOT EXISTS job_descriptions (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,resume_id text REFERENCES resumes(id) ON DELETE SET NULL,content text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ats_analyses (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,resume_id text REFERENCES resumes(id) ON DELETE SET NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS interview_questions (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,resume_id text REFERENCES resumes(id) ON DELETE SET NULL,category text NOT NULL,question text NOT NULL,answer text NOT NULL,completed boolean NOT NULL DEFAULT false,saved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS interview_owner_idx ON interview_questions(user_id);
CREATE TABLE IF NOT EXISTS portfolio_pages (id text PRIMARY KEY,user_id text NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,resume_id text NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,slug text NOT NULL UNIQUE,visibility text NOT NULL DEFAULT 'private',password_hash text,theme text NOT NULL DEFAULT 'studio',analytics boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS resume_views (id text PRIMARY KEY,resume_id text NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,visitor text NOT NULL,referrer text NOT NULL,device text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS views_resume_date_idx ON resume_views(resume_id,created_at);
CREATE TABLE IF NOT EXISTS resume_downloads (id text PRIMARY KEY,resume_id text NOT NULL REFERENCES resumes(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS downloads_resume_date_idx ON resume_downloads(resume_id,created_at);
CREATE TABLE IF NOT EXISTS subscriptions (id text PRIMARY KEY,user_id text NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,plan text NOT NULL DEFAULT 'free',status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,title text NOT NULL,body text NOT NULL,read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
